changeSet.sql:
CREATE TABLE plots ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
estate_id uuid NOT NULL, block_id uuid, price_tier_id uuid NOT NULL, plot_number varchar(32) NOT NULL, is_corner boolean NOT NULL, status varchar(32) NOT NULL, intent varchar(32), orientation varchar(2), nominal_size_sqm numeric(12,2) NOT NULL, actual_area_sqm numeric(12,2), footprint geometry(Polygon,4326),
PRIMARY KEY (id) );
COMMENT ON COLUMN plots.nominal_size_sqm IS 'What this plot is SOLD AND PRICED as — the number on the deed and the invoice. Comes from its tier. Kept alongside actual_area_sqm rather than instead of it: a plot sold as 250 sqm may survey at 248.6, and keeping only one loses either the commercial truth or the physical truth.'; COMMENT ON COLUMN plots.actual_area_sqm IS 'What the SURVEY says, derived from footprint via ST_Area(footprint::geography) — square metres, a geography cast, never raw 4326 (which yields square degrees). Nullable, and MUST NEVER default to nominal_size_sqm: a plot with no footprint has no surveyed area, and copying the nominal value would manufacture a survey result nobody produced.'; COMMENT ON COLUMN plots.footprint IS 'This plot''s own boundary, SRID 4326. The within-estate double allocation — the same plot sold twice inside one estate — is the more common scam and is undetectable precisely BECAUSE plots have had no geometry. This column is what makes real ST_Intersects detection possible rather than a bounding-box heuristic.'; COMMENT ON COLUMN plots.is_corner IS 'With estates.corner_premium_pct this makes a corner plot''s price computable, which is why no corner price is stored anywhere.';
ALTER TABLE plots ADD CONSTRAINT chk_plots_status CHECK (status IN ('AVAILABLE_DEV', 'AVAILABLE_INV', 'RESERVED', 'SOLD')); ALTER TABLE plots ADD CONSTRAINT chk_plots_intent CHECK (intent IS NULL OR intent IN ('DEVELOPMENT', 'INVESTMENT')); ALTER TABLE plots ADD CONSTRAINT chk_plots_orientation CHECK (orientation IS NULL OR orientation IN ('N','S','E','W','NE','NW','SE','SW')); ALTER TABLE plots ADD CONSTRAINT chk_plots_nominal_size_positive CHECK (nominal_size_sqm > 0); ALTER TABLE plots ADD CONSTRAINT chk_plots_actual_area_positive CHECK (actual_area_sqm IS NULL OR actual_area_sqm > 0);
